# Test the fill from paired row rule
def apply_transformation(grid):
    """Replace 3s with values from paired row (15-r) where available"""
    out = [row[:] for row in grid]

    # First find a master complete row for each pattern type
    # Look at rows 0-1 and 6-9 which are complete and repeat patterns
    complete_rows = [0, 1, 6, 7, 8, 9, 11]

    # Group rows by their non-3 pattern and find complete masters
    row_groups = {}
    for r in range(16):
        # Create a canonical pattern by removing 3s
        pattern = []
        for c in range(16):
            v = grid[r][c]
            pattern.append(v if v != 3 else "M")  # M = missing

        if pattern not in row_groups:
            row_groups[pattern] = []
        row_groups[pattern].append(r)

    print("Row groups (by non-3 pattern):")
    for p, rows in row_groups.items():
        print(f"  Pattern {p[:5]}...: rows {rows}")

    # Mapping: each row with 3s -> which complete row to copy from
    # Row 4, 10, 5 have similar 3-position pattern at cols 4-6
    # Let's fill by copying from the paired row

    # Fill each row that has 3s
    for r in range(16):
        pattern = []
        for c in range(16):
            v = grid[r][c]
            pattern.append(v if v != 3 else "M")

        # Find which complete row has this exact pattern
        found = False
        for cr in complete_rows:
            pattern_c = []
            for c in range(16):
                v = grid[cr][c]
                pattern_c.append(v if v != 3 else "M")
            if pattern == pattern_c:
                # Found a complete match! Just copy values at 3 positions
                for c in range(16):
                    if grid[r][c] == 3:
                        out[r][c] = grid[cr][c]
                found = True
                print(f"Row {r} 3s filled from complete row {cr}")
                break

    # For rows where no complete match, try paired row (15-r)
    for r in range(16):
        if 3 in out[r]:
            # This row still has 3s, fill from paired row
            if r != 15 - r:  # Don't self-pair
                r_paired = 15 - r
                for c in range(16):
                    if out[r][c] == 3:
                        out[r][c] = out[r_paired][c]
                print(f"Row {r} 3s filled from paired row {r_paired}")
            else:
                # Self-pairing row, try other complete rows
                for cr in complete_rows:
                    if cr != r:
                        for c in range(16):
                            if out[r][c] == 3:
                                out[r][c] = grid[cr][c]
                        print(f"Row {r} 3s filled from complete row {cr}")
                        break

    return out

